generate.initial_sparql:
PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catLabel
       (SUM(xsd:decimal(?cashFlowSum)) AS ?totalCashFlow)
       (SUM(xsd:decimal(?scenarioChangeSum)) AS ?totalScenarioChange)
       (SUM(xsd:decimal(?allocationPctSum)) AS ?totalAllocationPct)
       (SUM(xsd:decimal(?sectorInvestSum)) AS ?totalSectorInvestment)
WHERE {
  {
    SELECT DISTINCT ?investorId ?cat WHERE {
      ?ph a wm:PortfolioHolding ;
          wm:investorId ?investorId ;
          wm:hasCategory ?cat .
    }
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?amount)) AS ?cashFlowSum) WHERE {
      ?cf a wm:CashFlow ;
          wm:investorId ?investorId ;
          wm:amount ?amount .
    } GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?delta)) AS ?scenarioChangeSum) WHERE {
      ?sr a wm:ScenarioRebalancing ;
          wm:investorId ?investorId ;
          wm:currentAllocationPct ?curr ;
          wm:newAllocationPct ?new .
      BIND (xsd:decimal(?new) - xsd:decimal(?curr) AS ?delta)
    } GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?allocationPct)) AS ?allocationPctSum) WHERE {
      ?sa a wm:SectorAllocation ;
          wm:investorId ?investorId ;
          wm:allocationPct ?allocationPct .
    } GROUP BY ?investorId
  }
  OPTIONAL {
    SELECT ?investorId (SUM(xsd:decimal(?currentValue)) AS ?sectorInvestSum) WHERE {
      ?ph2 a wm:PortfolioHolding ;
            wm:investorId ?investorId ;
            wm:currentValue ?currentValue .
    } GROUP BY ?investorId
  }
  ?cat rdfs:label ?catLabel .
}
GROUP BY ?catLabel

